mapper.select:
SELECT o.order_no, c.center_no, c.center_name, o.status_code, cc.code_name AS status_name, o.ordered_at FROM wms.inbound_order o JOIN wms.center_info c ON c.center_info_id = o.center_info_id LEFT JOIN wms.code_group cg ON cg.group_code = 'INB_STATUS' AND cg.is_active = TRUE LEFT JOIN wms.common_code cc ON cc.code_group_id = cg.code_group_id AND cc.code_value = o.status_code AND cc.is_active = TRUE
AND c.center_no = #{center_no}
AND o.status_code = #{status_code}
ORDER BY o.ordered_at DESC, o.order_no

mapper.update:
UPDATE wms.inbound_order
   SET status_code = #{to_status},
       updated_at = now(),
       updated_by = #{changed_by}
 WHERE order_no = #{order_no}
   AND status_code = #{from_status}
